#include SIRKIT_SOURCE
#include <atomic>
#include <chrono>
#include <cstdio>
#include <random>
#include <string>
#include <vector>
#ifdef FLOAT_TYPE
using Value=long double;
#else
using Value=std::int64_t;
#endif
struct P {Value k,m;};
using Clock=std::chrono::steady_clock;
static void barrier(){std::atomic_signal_fence(std::memory_order_seq_cst);}
template<int mode,class Hull> [[gnu::noinline]] static long double query(Hull const& h,std::vector<Value>const& qs){
 long double sum=0;barrier();
 for(Value x:qs){
  if constexpr(mode==0)sum+=h.query(x);
  if constexpr(mode==1)sum+=*h.query_optional(x);
  if constexpr(mode==2){auto v=h.query_line(x);sum+=static_cast<long double>(v.first)+v.second;}
  if constexpr(mode==3){auto v=*h.query_line_optional(x);sum+=static_cast<long double>(v.first)+v.second;}
  if constexpr(mode==4){auto v=h.query_with_line(x);sum+=static_cast<long double>(v.value)+v.k+v.m;}
  if constexpr(mode==5){auto v=*h.query_with_line_optional(x);sum+=static_cast<long double>(v.value)+v.k+v.m;}
 }
 barrier();return sum;
}
template<int mode,class Hull>static void measure(const char* prefix,const char* name,Hull const&h,std::vector<Value>const&qs){auto t=Clock::now();auto sum=query<mode>(h,qs);auto ns=std::chrono::duration<double,std::nano>(Clock::now()-t).count()/qs.size();std::printf("%s:%s %.9f %.12Le\n",prefix,name,ns,sum);}
template<Objective obj>static void bench(){
 for(auto shape:{"one","two","tiny","random","parabola","inverse","duplicates","wide","wide_two"}){
  const std::string s=shape;const int n=s=="one"?1:(s=="two"||s=="wide_two")?2:s=="tiny"?32:(s=="parabola"||s=="inverse")?20000:50000;
  std::mt19937_64 rng(982157);std::vector<P> ps;ps.reserve(n);
  for(int i=0;i<n;++i){std::int64_t k,m;
   if(s=="parabola"||s=="inverse"){k=i-n/2;m=k*k;if(s=="inverse")m=-m;}
   else if(s=="duplicates"){k=31;m=-29;}
   else{k=static_cast<std::int64_t>(rng()%2000000001)-1000000000;m=(s=="wide"||s=="wide_two")?static_cast<std::int64_t>(rng()%UINT64_C(2000000000000000001))-INT64_C(1000000000000000000):static_cast<std::int64_t>(rng()%2000000001)-1000000000;}
#ifdef FLOAT_TYPE
   ps.push_back({Value(k)/4,Value(m)/8});
#else
   ps.push_back({k,m});
#endif
  }
  std::vector<Value>qs(200000);for(auto&x:qs){x=static_cast<std::int64_t>(rng()%2000000001)-1000000000;
#ifdef FLOAT_TYPE
   x/=4;
#endif
  }
  const int reps=n<=2?200000:n<=32?10000:3;double ns=0;std::uint64_t checksum=0;std::string prefix=std::string(obj==MINIMIZE?"min:":"max:")+s;
  for(int rep=0;rep<reps;++rep){auto t=Clock::now();LineContainer<Value,obj>h;for(auto p:ps)h.add(p.k,p.m);barrier();ns+=std::chrono::duration<double,std::nano>(Clock::now()-t).count();checksum+=h.size();}
  std::printf("%s:build %.9f %llu\n",prefix.c_str(),ns/reps,static_cast<unsigned long long>(checksum));
  LineContainer<Value,obj>h;for(auto p:ps)h.add(p.k,p.m);
  measure<0>(prefix.c_str(),"query",h,qs);measure<1>(prefix.c_str(),"optional",h,qs);measure<2>(prefix.c_str(),"line",h,qs);measure<3>(prefix.c_str(),"line_optional",h,qs);measure<4>(prefix.c_str(),"value_line",h,qs);measure<5>(prefix.c_str(),"value_line_optional",h,qs);
 }
}
int main(){bench<MINIMIZE>();bench<MAXIMIZE>();}

