from pathlib import Path
import subprocess as sp,json,hashlib,statistics,time,contextlib,fcntl,sys
p=Path(__file__).parent;variants=['baseline','control',sys.argv[1] if len(sys.argv)>1 else 'order'];candidate=variants[-1];modes={'gcc':['g++'],'clang':['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']};types=['int'] if candidate in ['order_likely','denominator'] else ['int','float'];builds=[]
for m,cc in modes.items():
 for ty in types:
  for v in variants:
   cmd=['taskset','-c','6',*cc,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DSIRKIT_SOURCE="{p/(v+".hpp")}"',str(p/'micro.cpp'),'-o',str(p/(m+'_'+ty+'_'+v))]
   if ty=='float':cmd+=['-DFLOAT_TYPE']
   r=sp.run(cmd,capture_output=True,text=True);assert not r.returncode,r.stderr;builds.append(dict(compiler=m,type=ty,variant=v,command=cmd))
raw={m:{ty:{v:{}for v in variants}for ty in types}for m in modes};sums={}
with contextlib.ExitStack()as stack:
 for name in ['/tmp/sirkit_performance_cpu14.lock','/tmp/atcoder_full_performance_20261018/benchmark.lock']:
  f=stack.enter_context(open(name,'a'));fcntl.flock(f,fcntl.LOCK_EX)
 for rep in range(7):
  for m in modes:
   for ty in types:
    vs=variants[rep%3:]+variants[:rep%3]
    for v in vs:
     out=sp.check_output(['taskset','-c','14',str(p/(m+'_'+ty+'_'+v))],text=True)
     for line in out.splitlines():
      k,t,checksum=line.split();raw[m][ty][v].setdefault(k,[]).append(float(t));key=(ty,k);assert key not in sums or sums[key]==checksum,(m,ty,v,k,sums[key],checksum);sums[key]=checksum
  print('micro round',rep+1,'done',flush=True)
med={m:{ty:{v:{k:statistics.median(xs)for k,xs in items.items()}for v,items in vs.items()}for ty,vs in types_.items()}for m,types_ in raw.items()};ratios={m:{ty:{v:{k:x/vs['baseline'][k]for k,x in items.items()}for v,items in vs.items()}for ty,vs in types_.items()}for m,types_ in med.items()}
(p/('micro_'+candidate+'_results.json')).write_text(json.dumps(dict(raw_ns=raw,median_ns=med,ratios=ratios,builds=builds,harness_sha256=hashlib.sha256((p/'micro.cpp').read_bytes()).hexdigest()),indent=2)+'\n')
for m,types_ in ratios.items():
 for ty,vs in types_.items():
  print(m,ty,'outside 3pct',[(k,round(x,4),round(vs['control'][k],4))for k,x in vs[candidate].items()if x>1.03 or x<.97],flush=True)

